// A board: a DOM plane you arrange a design system on. The cards are real elements — a token card carries its painted value,
// its text value and the rule behind it, and a part card holds a live component — and the lines behind them say which part
// uses which token. Nothing is painted on a canvas: the page's own text, focus, tokens and dark mode are the board's, so the
// map is readable with the stylesheet off and a reader who never points at it still gets every relationship as text.
import { shapePath } from "@cssints/css-grammar/shape";
import { createPanZoom } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, createMemo, createSignal, For, merge, Show } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { connectorBetween, curveBetween } from "./route.ts";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the card list, `data-part` and the caller's class merged in. */
export type BoardPartProps = PartProps;

/** A card on the plane. A token is data; a part is a component the page gives a preview of. */
export interface BoardNode {
  readonly id: string;
  /** The card's corner on the plane, in plane pixels. */
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  /** `token` paints a swatch and a value; `part` holds a live component in its body. */
  readonly kind: "token" | "part";
  /** The card's name: a token's CSS name (`color.highlight`) or a component's (`Button`). */
  readonly title: string;
  /** The token's value as text (`6px`), or a part's short role; a colour's value is the swatch. */
  readonly detail?: string | undefined;
  /** The rule behind a token: why it exists, in the design system's own words. */
  readonly note?: string | undefined;
  /** A token's painted value, e.g. `var(--color-highlight)`. */
  readonly swatch?: string | undefined;
  /**
   * The CSS property the token feeds (`color`, `border-radius`), which is what makes the card's value editable: a typed
   * value is judged by `CSS.supports(property, …)` before the plane takes it. A token without it stays text, and a part
   * card always does.
   */
  readonly property?: string | undefined;
}

/** A line from one card to another: a part uses a token, a token derives from another. */
export interface BoardEdge {
  readonly from: string;
  readonly to: string;
  readonly label?: string | undefined;
  /**
   * How the line is drawn: `arrow` is the curve of perfect-arrows with its head (the default); `shape` is a CSS
   * connector, a `border-shape` where the browser has one and the same curve as an SVG path where it has not. A shape
   * line routes around nothing, so it is for a pair that does not cross the map.
   */
  readonly line?: "arrow" | "shape" | undefined;
}

export interface BoardProps extends Renderable<BoardPartProps, void> {
  /** The board's name, which is the figure's caption and the plane's accessible name. */
  readonly label: string;
  /** The cards, in the order a reader meets them. */
  readonly nodes: ReadonlyArray<BoardNode>;
  /** The lines, and the relationships the cards state in words. */
  readonly edges?: ReadonlyArray<BoardEdge> | undefined;
  /** The card that starts current, so a page can open the board on a token; Escape drops it. */
  readonly defaultSelected?: string | undefined;
  /** The look the plane starts under; the switch in its settings bar moves it (the theme's `data-mode` look). */
  readonly defaultMode?: "light" | "dark" | undefined;
  /**
   * The content's size on the plane, in px. Left out, the content is the frame itself; a map bigger than the frame gives
   * its own size, and pan and zoom explore it (Fit is the smallest scale).
   */
  readonly width?: number | undefined;
  readonly height?: number | undefined;
  /** The scale the plane opens at; `0.5` is the whole map in the frame, `1` the map's own size. @default 1 */
  readonly defaultScale?: number | undefined;
  /** A part card's body: the page's own component, inert to the pointer because a card is not a control. */
  readonly preview?: ((node: BoardNode) => JSX.Element | undefined) | undefined;
  readonly class?: string | undefined;
}

/** Arrow-key nudge, in plane px; Shift multiplies it. */
const NUDGE = 8;
const NUDGE_SHIFT = 24;

interface Position {
  readonly x: number;
  readonly y: number;
}

interface Moving {
  readonly id: string;
  readonly pointerId: number;
  /** Where the pointer started, and where the card was then. */
  readonly at: Position;
  readonly from: Position;
}

/**
 * A token's custom property: the theme names it after the token's path (`color.highlight` → `--color-highlight`), so the
 * card's title is the whole address of the value its field edits.
 */
const tokenOf = (node: BoardNode): string => `--${node.title.replaceAll(".", "-")}`;

/** A field on a card owns the pointer: typing in it and selecting text are not a drag. */
const isField = (target: EventTarget | null): boolean =>
  target instanceof Element && target.closest("input, textarea, select, [contenteditable]") !== null;

const rootClass = css.cn(
  css.display("grid"),
  css.gap(t.space._2),
  css.width("100%"),
  css.margin("0"),
);

const captionClass = css.cn(
  css.display("grid"),
  css.gap("2px"),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.text),
);

const captionNameClass = css.cn(css.fontWeight("600"), css.fontSize(t.font.size));

const hintClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));

// The plane: the primitive's box, with the rounded corners and the focus ring. `touch-action: none` is the touch pan, and the
// grab cursor says the empty plane is draggable — a card says the same for itself.
const viewportClass = css.cn(
  css.position("relative"),
  css.height("26rem"),
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.bg(t.color.page),
  // a faint dot grid says "plane" rather than "card"; it is the page's border colour, so it follows the mode
  css.backgroundImage("radial-gradient(var(--color-border) 1px, transparent 1px)"),
  css.backgroundSize("16px 16px"),
  css.touchAction("none"),
  css.cursor("grab"),
  css.outline("none"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

// The transform is the primitive's, inline. The origin is the centre, which is the maths `setScale` assumes: a zoom keeps the
// point under the cursor still only about that origin. The plane is the frame; the world inside carries the content's own
// size, centred on the plane, so a map bigger than the frame is panned instead of cropped at build time.
const planeClass = css.cn(css.position("absolute"), css.inset("0"), css.transformOrigin("50% 50%"));

const worldClass = css.cn(
  css.position("absolute"),
  css.left("50%"),
  css.top("50%"),
  css.width("var(--board-width, 100%)"),
  css.height("var(--board-height, 100%)"),
  css.transform("translate(-50%, -50%)"),
);

const cardsClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.margin("0"),
  css.padding("0"),
  css.listStyle("none"),
);

// The arrows are drawn over the cards, as a whiteboard's are: a connection is a fact about the map, so it is never hidden by
// a card it crosses. They are thin on purpose — a map with twenty of them is read through the lines, not around them.
const edgesClass = css.cn(
  css.position("absolute"),
  css.zIndex("3"),
  css.inset("0"),
  css.width("100%"),
  css.height("100%"),
  css.overflow("visible"),
  css.pointerEvents("none"),
);

const lineClass = css.cn(
  css.stroke(t.color.borderHover),
  css.strokeWidth("1.25"),
  css.fill("none"),
  css.strokeLinecap("round"),
);

// The lines a current card touches: the same highlight the card's border takes, so the blast radius reads as one picture.
const lineLiveClass = css.cn(
  css.stroke(t.color.highlight),
  css.fill("none"),
  css.strokeWidth("2.5"),
  css.strokeLinecap("round"),
);

const arrowHeadClass = css.cn(css.stroke("none"), css.fill(t.color.borderHover));

const arrowHeadLiveClass = css.cn(arrowHeadClass, css.fill(t.color.highlight));

const edgeAwayClass = css.cn(css.opacity("0.2"));

// A CSS connector: the curve is the element's border, so border-shape draws the line and nothing else. The fallback is
// the same shape() as an SVG path (shapePath), which keeps its width under the non-uniform scale of the plane's box.
const connectorClass = css.cn(css.position("absolute"), css.zIndex("3"), css.pointerEvents("none"));

const connectorNativeClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.borderWidth("2px"),
  css.borderStyle("solid"),
  css.borderColor(t.color.borderHover),
  css.borderShape("var(--_shape)"),
  // a browser without the property would paint the whole rectangle: drop the border instead
  css.supports("not (border-shape: shape(from 0 0, line to 1px 1px))")(css.borderWidth("0")),
);

const connectorSvgClass = css.cn(
  css.position("absolute"),
  css.inset("0"),
  css.width("100%"),
  css.height("100%"),
  css.overflow("visible"),
  css.supports("(border-shape: shape(from 0 0, line to 1px 1px))")(css.display("none")),
);

const connectorPathClass = css.cn(
  css.fill("none"),
  css.stroke(t.color.borderHover),
  css.strokeWidth("2px"),
  css.vectorEffect("non-scaling-stroke"),
);

const cardClass = css.cn(
  css.position("absolute"),
  css.zIndex("2"),
  css.display("grid"),
  css.gridTemplateRows("auto 1fr"),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.boxShadow("0 1px 2px rgb(0 0 0 / 0.08)"),
  css.cursor("grab"),
  css.touchAction("none"),
  css.transition("border-color 120ms, opacity 120ms"),
);

const currentCardClass = css.cn(
  css.borderColor(t.color.highlight),
  css.boxShadow("inset 0 0 0 1px", t.color.highlight),
);

const awayClass = css.cn(css.opacity("0.45"), css.zIndex("0"));

const headClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.width("100%"),
  css.boxSizing("border-box"),
  css.padding(t.space._2),
  css.border("none"),
  css.borderRadius(t.radius.md),
  css.bg("transparent"),
  css.color("inherit"),
  css.fontFamily("inherit"),
  css.textAlign("start"),
  css.cursor("grab"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

const swatchClass = css.cn(
  css.width("1.5rem"),
  css.height("1.5rem"),
  css.flex("none"),
  css.borderRadius(t.radius.sm),
  css.border("1px solid", t.color.border),
);

const titleClass = css.cn(
  css.fontSize(t.font.size),
  css.fontWeight("600"),
  css.overflowWrap("anywhere"),
  css.minWidth("0"),
);

const bodyClass = css.cn(
  css.display("grid"),
  css.gap(t.space._1),
  css.alignContent("start"),
  css.padding(t.space._2),
  css.paddingBlock("0"),
  css.borderTop("1px solid", t.color.border),
  css.fontSize(t.font.sizeSm),
  css.overflowWrap("anywhere"),
);

const previewClass = css.cn(css.display("grid"), css.placeItems("center"), css.padding(t.space._2));

const valueClass = css.cn(
  css.width("max-content"),
  css.paddingInline(t.space._1),
  css.borderRadius(t.radius.sm),
  css.bg(t.color.buttonBackground),
  css.fontFamily("monospace"),
  css.fontSize(t.font.sizeSm),
);

// The same chip as a field: a token's value is typed where it is read, and a value the property refuses keeps the invalid
// ring instead of reaching the plane.
const fieldClass = css.cn(
  valueClass,
  css.width("100%"),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.bg(t.color.surface),
  css.fontFamily("inherit"),
  css.color("inherit"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("1px")),
  css.attr("aria-invalid", "true")(css.borderColor(t.color.invalid)),
);

const outlineClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.text));

const outlineSummaryClass = css.cn(
  css.width("max-content"),
  css.cursor("pointer"),
  css.color(t.color.muted),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

const outlineListClass = css.cn(
  css.display("grid"),
  css.gap("2px"),
  css.margin("0"),
  css.marginBlockStart(t.space._1),
  css.padding("0"),
  css.listStyle("none"),
  css.maxBlockSize("10rem"),
  css.overflowY("auto"),
);

const outlineItemClass = css.cn(
  css.display("flex"),
  css.gap(t.space._2),
  css.alignItems("baseline"),
  css.width("100%"),
  css.boxSizing("border-box"),
  css.paddingBlock("2px"),
  css.paddingInline(t.space._1),
  css.border("none"),
  css.borderRadius(t.radius.sm),
  css.bg("transparent"),
  css.color("inherit"),
  css.fontFamily("inherit"),
  css.fontSize("inherit"),
  css.textAlign("start"),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

const outlineCurrentClass = css.cn(css.color(t.color.highlight), css.fontWeight("600"));

const outlineKindClass = css.cn(css.marginInlineStart("auto"), css.color(t.color.muted));

const noteClass = css.cn(css.margin("0"), css.color(t.color.muted));

const zoomClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.fontVariantNumeric("tabular-nums"),
);

const settingsClass = css.cn(
  css.display("flex"),
  css.flexWrap("wrap"),
  css.alignItems("center"),
  css.gap(t.space._2),
);

const modeClass = css.cn(css.marginInlineStart("auto"));

const statusClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.text));

/**
 * A board: a plane of cards you arrange, styled and driven by the primitive's own gestures.
 *
 * `createPanZoom` owns the plane — the drag, the pinch, `Ctrl`/`⌘` + wheel, `+` / `-` / `0`, the arrows when the plane has
 * the focus, and the live value — with `bounds: "free"`, because a board is not one image fitted to its box. The skin owns
 * the cards: a token's swatch, value and rule, a part's live preview, the pointer drag of a card, the arrow nudge when a card
 * has the focus, and the current card that dims everything it does not touch.
 *
 * The data is the cards' text. A token card states the parts that use it, a part card states the tokens it uses, and the SVG
 * lines are decoration (`aria-hidden`): with the stylesheet off the board is a list of names, values, rules and relationships.
 *
 * Two things make it a management view rather than a picture. A token card whose `property` is known carries its value as a
 * field: what is typed there is checked with `CSS.supports` and set on the plane as the theme's own custom property, so the
 * swatch, the cards made of that token and the real components in the previews all move at once. The outline is the map's
 * linear reading: every card in document order, with what it reaches, and one press brings it to the middle of the frame and
 * the focus.
 */
export const Board = (props: BoardProps): JSX.Element => {
  const pan = createPanZoom({
    bounds: "free",
    // a map that is wider and taller than the box: `0` (and Fit) pulls the whole of it into view
    min: 0.5,
    max: 2,
    step: 0.25,
    get defaultScale() {
      return props.defaultScale ?? 1;
    },
    get labels() {
      return { viewport: props.label };
    },
  });

  const [positions, setPositions] = createSignal<Readonly<Record<string, Position>>>({});
  const [current, setCurrent] = createSignal<string | undefined>(props.defaultSelected);
  // the mise-en-mode look over the plane: the same tokens, the mode the theme registers for `data-mode`
  const [mode, setMode] = createSignal<"light" | "dark">(props.defaultMode ?? "light");
  // The values typed into the plane, by node id; a missing key is the theme's own. They are set on the world element as the
  // theme's custom properties, so the card's swatch, every other token made of them and every real component that reads
  // them move together: one edit, the whole system.
  const [values, setValues] = createSignal<Readonly<Record<string, string>>>({});
  // The plane's own values, read off it rather than off the data: a colour's `detail` is its role ("accent"), and the value
  // a field starts from is what the plane uses. Read once the world is placed, and again after a mode switch — the same
  // token is another colour under the dark look.
  const [planeValues, setPlaneValues] = createSignal<Readonly<Record<string, string>>>({});
  const [placed, setPlaced] = createSignal(false);

  // the plane as the drag measures it, and the pointer's gesture
  let world: HTMLElement | undefined;
  let moving: Moving | undefined;

  const byId = createMemo(() => new Map(props.nodes.map((node) => [node.id, node])));
  const edges = (): ReadonlyArray<BoardEdge> => props.edges ?? [];

  const placement = (node: BoardNode): Position => positions()[node.id] ?? { x: node.x, y: node.y };

  const boxOf = (node: BoardNode) => {
    const at = placement(node);
    return { x: at.x, y: at.y, width: node.width, height: node.height };
  };

  // a split effect: the compute phase names the dependencies, the apply phase reads the plane
  createEffect(
    () => [placed(), mode(), props.nodes] as const,
    () => {
      const element = world;
      if (!placed() || element === undefined) {
        return;
      }
      const style = getComputedStyle(element);
      setPlaneValues(
        Object.fromEntries(
          props.nodes.flatMap((node) =>
            node.property === undefined
              ? []
              : [[node.id, style.getPropertyValue(tokenOf(node)).trim()] as const],
          ),
        ),
      );
    },
  );

  /** What a token card's field shows: what was typed over the theme's value, else the plane's own value. */
  const shown = (node: BoardNode): string =>
    values()[node.id] ?? planeValues()[node.id] ?? node.detail ?? "";

  /**
   * What `detail` still means once the value is a field: a step's detail *is* its value (`6px`), so the field shows it; a
   * colour's value is its swatch, and its detail is what the colour is for ("accent", "hints"), which stays text.
   */
  const roleOf = (node: BoardNode): string | undefined =>
    node.property === undefined ? node.detail : node.swatch === undefined ? undefined : node.detail;

  /** An empty field is the theme's own value, so it drops the override rather than setting an empty one. */
  const setValue = (node: BoardNode, next: string | undefined): void => {
    setValues((all) => {
      const copy = { ...all };
      if (next === undefined) {
        delete copy[node.id];
      } else {
        copy[node.id] = next;
      }
      return copy;
    });
  };

  /** Enter or a blur takes a typed value where `CSS.supports` does; anything else keeps the plane as it was. */
  const commit = (node: BoardNode, input: HTMLInputElement): void => {
    const text = input.value.trim();
    if (text !== "" && !CSS.supports(node.property ?? "", text)) {
      input.setAttribute("aria-invalid", "true");
      return;
    }
    input.removeAttribute("aria-invalid");
    setValue(node, text === "" ? undefined : text);
  };

  /** Escape abandons what was typed: the field and the plane go back to the value they had. */
  const revert = (node: BoardNode, input: HTMLInputElement): void => {
    input.value = shown(node);
    input.removeAttribute("aria-invalid");
  };

  /** The typed values as the theme's custom properties, applied to the world so every card and preview follows them. */
  const overrides = (): Record<string, string> => {
    const typed = values();
    return Object.fromEntries(
      props.nodes.flatMap((node) => {
        const value = typed[node.id];
        return node.property !== undefined && value !== undefined
          ? [[tokenOf(node), value] as const]
          : [];
      }),
    );
  };

  const uses = (id: string): string[] =>
    edges().flatMap((edge) => {
      if (edge.from !== id) {
        return [];
      }
      const to = byId().get(edge.to);
      return to === undefined ? [] : [to.title];
    });

  const usedBy = (id: string): string[] =>
    edges().flatMap((edge) => {
      if (edge.to !== id) {
        return [];
      }
      const from = byId().get(edge.from);
      return from === undefined ? [] : [from.title];
    });

  /** The card is the current one, or one of its neighbours; with nothing current every card is in. */
  const related = (id: string): boolean => {
    const chosen = current();
    if (chosen === undefined || chosen === id) {
      return true;
    }
    return edges().some(
      (edge) =>
        (edge.from === chosen && edge.to === id) || (edge.to === chosen && edge.from === id),
    );
  };

  /** What the card knows about its own connections, in words: never a value that only a line carries. */
  const reads = (id: string): string => {
    const node = byId().get(id);
    if (node === undefined) {
      return "";
    }
    if (node.kind === "token") {
      const parts = usedBy(id);
      return parts.length === 0 ? "Used by nothing yet" : `Used by ${parts.join(", ")}`;
    }
    const tokens = uses(id);
    return tokens.length === 0 ? "Uses no tokens yet" : `Uses ${tokens.join(", ")}`;
  };

  const summary = (): string => {
    const chosen = current();
    if (chosen === undefined) {
      return "";
    }
    const node = byId().get(chosen);
    return node === undefined ? "" : `${node.title}, current. ${reads(chosen)}.`;
  };

  /** Keep a card on the plane: a card dragged past an edge stays reachable. */
  const bound = (value: number, limit: number): number =>
    Math.min(Math.max(0, limit), Math.max(0, value));

  const moveTo = (node: BoardNode, next: Position): void => {
    setPositions((all) => ({
      ...all,
      [node.id]: {
        x: bound(next.x, (world?.clientWidth ?? 0) - node.width),
        y: bound(next.y, (world?.clientHeight ?? 0) - node.height),
      },
    }));
  };

  const startDrag = (event: PointerEvent, node: BoardNode): void => {
    if (event.button !== 0) {
      return;
    }
    // a token's field keeps the pointer, and the current card with it: selecting text is not a drag
    if (isField(event.target)) {
      event.stopPropagation();
      return;
    }
    // the card takes the pointer, so the plane does not pan under it
    event.stopPropagation();
    setCurrent(node.id);
    const element = event.currentTarget;
    if (element instanceof Element) {
      try {
        element.setPointerCapture(event.pointerId);
      } catch {
        // a synthetic pointer (a test, assistive technology) is not active: there is nothing to capture
      }
    }
    moving = {
      id: node.id,
      pointerId: event.pointerId,
      at: { x: event.clientX, y: event.clientY },
      from: placement(node),
    };
  };

  const drag = (event: PointerEvent): void => {
    const entry = moving;
    if (entry === undefined || entry.pointerId !== event.pointerId) {
      return;
    }
    const node = byId().get(entry.id);
    if (node === undefined) {
      return;
    }
    // the plane is scaled: a screen pixel is one `scale()`th of a plane pixel
    const scale = pan.scale();
    moveTo(node, {
      x: entry.from.x + (event.clientX - entry.at.x) / scale,
      y: entry.from.y + (event.clientY - entry.at.y) / scale,
    });
  };

  const drop = (event: PointerEvent): void => {
    if (moving !== undefined && moving.pointerId === event.pointerId) {
      moving = undefined;
    }
  };

  const nudge = (event: KeyboardEvent, node: BoardNode): void => {
    const step = event.shiftKey ? NUDGE_SHIFT : NUDGE;
    const dx = event.key === "ArrowLeft" ? -step : event.key === "ArrowRight" ? step : 0;
    const dy = event.key === "ArrowUp" ? -step : event.key === "ArrowDown" ? step : 0;
    if (dx === 0 && dy === 0) {
      return;
    }
    event.preventDefault();
    // the plane pans on these keys; a card has the focus, so it is the card that moves
    event.stopPropagation();
    const at = placement(node);
    moveTo(node, { x: at.x + dx, y: at.y + dy });
  };

  const planeKeyDown = (event: KeyboardEvent): void => {
    if (event.key === "Escape") {
      setCurrent(undefined);
      return;
    }
    pan.viewportProps.onKeyDown(event);
  };

  /**
   * The outline's one action: make a card current, put it in the middle of the frame and give it the focus. The world is
   * centred on the plane and the plane's transform origin is its own centre, so the pan that centres a card is the card's
   * distance from the world's centre, scaled, less the pan it already has.
   */
  const goTo = (node: BoardNode): void => {
    setCurrent(node.id);
    const element = world;
    if (element !== undefined) {
      const at = placement(node);
      const scale = pan.scale();
      const behind = pan.offset();
      pan.panBy(
        -((at.x + node.width / 2) - element.clientWidth / 2) * scale - behind.x,
        -((at.y + node.height / 2) - element.clientHeight / 2) * scale - behind.y,
      );
    }
    // the plane is transformed, not scrolled: focusing without a scroll keeps the centring above exact
    element
      ?.querySelector<HTMLElement>(
        `[data-node="${CSS.escape(node.id)}"] [data-part="board-head"]`,
      )
      ?.focus({ preventScroll: true });
  };

  const routed = createMemo(() =>
    edges().flatMap((edge) => {
      if (edge.line === "shape") {
        return [];
      }
      const from = byId().get(edge.from);
      const to = byId().get(edge.to);
      if (from === undefined || to === undefined) {
        return [];
      }
      const curve = curveBetween(boxOf(from), boxOf(to));
      return curve === undefined ? [] : [{ edge, curve }];
    }),
  );

  /** The shape edges: one shape() string drives both the border-shape and the path, so they cannot drift apart. */
  const connectors = createMemo(() =>
    edges().flatMap((edge) => {
      if (edge.line !== "shape") {
        return [];
      }
      const from = byId().get(edge.from);
      const to = byId().get(edge.to);
      if (from === undefined || to === undefined) {
        return [];
      }
      const connector = connectorBetween(boxOf(from), boxOf(to));
      if (connector === undefined) {
        return [];
      }
      return [{ edge, ...connector, path: shapePath(connector.shape).d }];
    }),
  );

  /** The edge touches the current card: the one relationship the selection lights up. */
  const live = (edge: BoardEdge): boolean => {
    const chosen = current();
    return chosen !== undefined && (edge.from === chosen || edge.to === chosen);
  };

  const viewport = merge(pan.viewportProps, {
    "data-part": "board-viewport",
    "aria-roledescription": "board",
    get "data-mode"() {
      return mode();
    },
    get class() {
      return viewportClass;
    },
    onKeyDown: planeKeyDown,
    onPointerDown: (event: PointerEvent) => {
      // a pointer on the empty plane drops the current card; a card stops its own before this runs
      setCurrent(undefined);
      pan.viewportProps.onPointerDown(event);
    },
  } as PartProps);

  const planeProps = merge(pan.imageProps, {
    "data-part": "board-plane",
    get class() {
      return planeClass;
    },
  } as PartProps);

  const own = {
    "data-part": "board",
    get class() {
      return css.cn(cardsClass, props.class);
    },
  } as unknown as PartProps;

  return (
    <figure
      data-part="board-frame"
      class={rootClass}
      style={
        {
          "--board-width": props.width === undefined ? "100%" : `${props.width}px`,
          "--board-height": props.height === undefined ? "100%" : `${props.height}px`,
        } as never
      }
    >
      <figcaption data-part="board-caption" class={captionClass}>
        <span class={captionNameClass}>{props.label}</span>
        <span class={hintClass}>
          Drag a card to place it, drag the plane to pan, and pick a card to see what it reaches. A
          token's value is a field: type another and the whole map follows. Keys: + and − zoom, 0
          fits the map, and arrows move the current card.
        </span>
      </figcaption>
      <div data-part="board-settings" class={settingsClass}>
        <Button size="sm" tone="quiet" onClick={pan.reset}>
          Fit
        </Button>
        <span {...pan.valueProps} data-part="board-zoom" class={zoomClass}>
          {pan.value()}
        </span>
        <span data-part="board-mode" class={modeClass}>
          <Button
            size="sm"
            tone="quiet"
            aria-pressed={mode() === "dark" ? "true" : "false"}
            onClick={() => setMode((look) => (look === "dark" ? "light" : "dark"))}
          >
            Dark mode
          </Button>
        </span>
      </div>
      <div {...viewport}>
        <div {...planeProps}>
          <div
            data-part="board-world"
            class={worldClass}
            style={overrides()}
            ref={(element) => {
              world = element;
              setPlaced(true);
            }}
          >
            <svg data-part="board-edges" class={edgesClass} aria-hidden="true">
              <For each={routed()}>
                {(item) => (
                  <g
                    data-part="board-edge"
                    data-from={item.edge.from}
                    data-to={item.edge.to}
                    class={current() !== undefined && !live(item.edge) ? edgeAwayClass : undefined}
                  >
                    <path class={live(item.edge) ? lineLiveClass : lineClass} d={item.curve.path} />
                    <polygon
                      class={live(item.edge) ? arrowHeadLiveClass : arrowHeadClass}
                      points={item.curve.head}
                    />
                  </g>
                )}
              </For>
            </svg>
            <For each={connectors()}>
              {(item) => (
                <div
                  data-part="board-connector"
                  data-from={item.edge.from}
                  data-to={item.edge.to}
                  class={css.cn(
                    connectorClass,
                    current() !== undefined && !live(item.edge) && edgeAwayClass,
                  )}
                  style={
                    {
                      left: `${item.left}px`,
                      top: `${item.top}px`,
                      width: `${item.width}px`,
                      height: `${item.height}px`,
                      "--_shape": item.shape,
                    } as never
                  }
                >
                  <div data-part="board-connector-native" class={connectorNativeClass} />
                  <svg
                    data-part="board-connector-fallback"
                    class={connectorSvgClass}
                    viewBox="0 0 100 100"
                    preserveAspectRatio="none"
                    aria-hidden="true"
                  >
                    <path class={connectorPathClass} d={item.path} />
                  </svg>
                </div>
              )}
            </For>
            {renderPart(props, own, undefined, (part) => (
              <ul {...part}>
                <For each={props.nodes}>
                  {(node) => {
                    const at = (): Position => placement(node);
                    return (
                      <li
                        data-part="board-card"
                        data-node={node.id}
                        data-kind={node.kind}
                        data-dim={current() !== undefined && !related(node.id) ? "true" : undefined}
                        class={css.cn(
                          cardClass,
                          current() === node.id && currentCardClass,
                          current() !== undefined && !related(node.id) && awayClass,
                        )}
                        style={{
                          left: `${at().x}px`,
                          top: `${at().y}px`,
                          width: `${node.width}px`,
                          height: `${node.height}px`,
                        }}
                        onPointerDown={(event) => startDrag(event, node)}
                        onPointerMove={drag}
                        onPointerUp={drop}
                        onPointerCancel={drop}
                      >
                        <button
                          type="button"
                          data-part="board-head"
                          class={headClass}
                          aria-current={current() === node.id ? "true" : undefined}
                          onClick={() => setCurrent(node.id)}
                          onKeyDown={(event) => nudge(event, node)}
                        >
                          <Show when={node.swatch}>
                            {(paint) => (
                              <span
                                data-part="board-swatch"
                                class={swatchClass}
                                style={{ background: paint() }}
                                aria-hidden="true"
                              />
                            )}
                          </Show>
                          <span class={titleClass}>{node.title}</span>
                        </button>
                        <div data-part="board-body" class={bodyClass}>
                          <Show when={node.kind === "part"}>
                            <div data-part="board-preview" class={previewClass} inert={true}>
                              {props.preview?.(node)}
                            </div>
                          </Show>
                          <Show when={node.property !== undefined}>
                            <input
                              data-part="board-value"
                              class={fieldClass}
                              type="text"
                              autocomplete="off"
                              spellcheck={false}
                              aria-label={`${node.title} value`}
                              value={shown(node)}
                              onKeyDown={(event) => {
                                // a text field owns its keys: the plane neither pans nor drops the card while typing
                                event.stopPropagation();
                                if (event.key === "Enter") {
                                  commit(node, event.currentTarget);
                                } else if (event.key === "Escape") {
                                  revert(node, event.currentTarget);
                                }
                              }}
                              onBlur={(event) => commit(node, event.currentTarget)}
                            />
                          </Show>
                          <Show when={roleOf(node) !== undefined}>
                            <code data-part="board-value" class={valueClass}>
                              {roleOf(node)}
                            </code>
                          </Show>
                          <Show when={node.note !== undefined}>
                            <p data-part="board-note" class={noteClass}>
                              {node.note}
                            </p>
                          </Show>
                          <p data-part="board-links" class={noteClass}>
                            {reads(node.id)}
                          </p>
                        </div>
                      </li>
                    );
                  }}
                </For>
              </ul>
            ))}
          </div>
        </div>
      </div>
      <details data-part="board-outline" class={outlineClass}>
        <summary class={outlineSummaryClass}>Outline ({props.nodes.length} cards)</summary>
        <ol class={outlineListClass}>
          <For each={props.nodes}>
            {(node) => (
              <li>
                <button
                  type="button"
                  data-part="board-outline-item"
                  data-outline={node.id}
                  class={css.cn(outlineItemClass, current() === node.id && outlineCurrentClass)}
                  aria-current={current() === node.id ? "true" : undefined}
                  onClick={() => goTo(node)}
                >
                  <span>{node.title}</span>
                  <span class={outlineKindClass}>
                    {node.kind} · {reads(node.id)}
                  </span>
                </button>
              </li>
            )}
          </For>
        </ol>
      </details>
      <p data-part="board-status" class={statusClass} role="status">
        {summary()}
      </p>
    </figure>
  );
};

import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the label, `data-part` and the caller's class merged in. */
export type BadgePartProps = PartProps;

export interface BadgeProps extends Renderable<BadgePartProps, void> {
  /** `neutral` is the quiet fill, `accent` the highlighted one, `quiet` a label with no fill. */
  readonly tone?: "neutral" | "accent" | "quiet";
  readonly class?: string;
  readonly children?: JSX.Element;
}

// A badge is a small label, fully round. The theme's radius steps stop at 16px (`radius.xl`), and a pill has to be rounder
// than half of its own height whatever that height is, so the value is 999px by hand: not a step, so not a token.
const badge = css.cv({
  base: css.cn(
    css.boxSizing("border-box"),
    css.display("inline-flex"),
    css.alignItems("center"),
    css.gap(t.space._1),
    css.width("max-content"),
    css.paddingBlock(t.space._1),
    css.paddingInline(t.space._2),
    css.border("1px solid", "transparent"),
    css.borderRadius("999px"),
    css.fontSize(t.font.sizeSm),
    css.fontWeight("500"),
    css.lineHeight(1),
    css.whiteSpace("nowrap"),
  ),
  variants: {
    tone: {
      neutral: css.cn(css.bg(t.color.buttonBackground), css.color(t.color.text)),
      accent: css.cn(css.bg(t.color.highlight), css.color(t.color.onHighlight)),
      quiet: css.cn(
        css.bg("transparent"),
        css.color(t.color.muted),
        css.border("1px solid", t.color.border),
      ),
    },
  },
  defaultVariants: { tone: "neutral" },
});

/** A badge: a small label for a state or a count, in one of three tones and always fully round. */
export const Badge = (props: BadgeProps): JSX.Element => {
  const own = {
    "data-part": "badge",
    get class() {
      return css.cn(badge({ tone: props.tone }), props.class);
    },
  } as PartProps;
  return renderPart(props, own, undefined, (part) => <span {...part}>{props.children}</span>);
};

import {
  type Button as ButtonController,
  type ButtonOptions,
  createButton,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { merge, omit, untrack } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** The button's state, as accessors: `render` can branch on `pressed()` without a re-render. */
export interface ButtonState {
  readonly pressed: () => boolean;
  readonly disabled: () => boolean;
}

/** What `render` gets: the button's props, its class merged with the caller's, and `data-part`. */
export type ButtonPartProps = PartProps;

export interface ButtonProps
  extends
    Omit<ButtonOptions, "id" | "onClick">,
    Omit<
      JSX.ButtonHTMLAttributes<HTMLButtonElement>,
      "type" | "children" | "class" | "onClick" | "disabled" | "value"
    >,
    Renderable<ButtonPartProps, ButtonState> {
  /** `neutral` is the default look, `accent` the highlighted one, `quiet` a button with no fill. */
  readonly tone?: "neutral" | "accent" | "quiet";
  readonly size?: "sm" | "md";
  readonly class?: string;
  readonly children?: JSX.Element;
  /** The primitive, once: a scenario fixture needs it; a page rarely does. */
  readonly onReady?: (button: ButtonController) => void;
  /** The activation happened (Enter, Space or pointer). */
  readonly onClick?: () => void;
}

// One cv() for every button. The states are the widget's, read off the attrs it announces — never a second copy of the
// pressed state — and an ancestor with `data-size="sm"` shrinks the button without a prop: a toolbar is the context.
// A button group is the context too, and it says which way it lies with its marker class (`_g-row` / `_g-column`): the
// `:first-child` and `:last-child` rules below style this element only where such a group is its ancestor.
const groupRow = css.within(css.attr("data-part", "button-group"), "row");
const groupColumn = css.within(css.attr("data-part", "button-group"), "column");

const button = css.cv({
  base: css.cn(
    css.boxSizing("border-box"),
    css.display("inline-flex"),
    css.alignItems("center"),
    css.justifyContent("center"),
    css.gap(t.space._2),
    css.width("max-content"),
    css.border("1px solid", "transparent"),
    css.borderRadius(t.radius.md),
    css.fontSize(t.font.size),
    css.fontWeight("500"),
    css.cursor("pointer"),
    css.transition("background-color 120ms, border-color 120ms"),
    css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
    css.attr("aria-pressed", "true")(
      css.bg(t.color.highlight),
      css.color(t.color.onHighlight),
      css.border("1px solid", t.color.highlight),
      css.hover(
        css.bg(t.color.highlightPressed),
        css.border("1px solid", t.color.highlightPressed),
      ),
    ),
    css.attr("aria-disabled", "true")(
      css.color(t.color.textDisabled),
      css.border("1px solid", t.color.borderDisabled),
      css.cursor("not-allowed"),
    ),
    // The container is the context: a compact toolbar sizes what it holds, and its rule sorts after a size variant.
    css.within(css.attr("data-size", "sm"))(
      css.padding(t.space._1, t.space._2),
      css.fontSize(t.font.sizeSm),
    ),
    // `ButtonGroup` is the other context: it marks itself `group("row")` or `group("column")`. Inside it every corner
    // is square first (the corners two neighbours share), then the two on the outer side come back for the first and
    // the last button — a lone button in a group is both, so it keeps its radius. Every button after the first slides
    // 1px into its neighbour, so their two 1px borders are one line. `data-part` keeps a `_g` ancestor that is not a
    // group of buttons out of it.
    groupRow(
      css.marginInlineStart("-1px"),
      css.borderStartStartRadius(0),
      css.borderEndStartRadius(0),
      css.borderStartEndRadius(0),
      css.borderEndEndRadius(0),
      css.firstChild(
        css.borderStartStartRadius(t.radius.md),
        css.borderEndStartRadius(t.radius.md),
      ),
      css.lastChild(css.borderStartEndRadius(t.radius.md), css.borderEndEndRadius(t.radius.md)),
    ),
    groupColumn(
      css.marginBlockStart("-1px"),
      css.borderStartStartRadius(0),
      css.borderEndStartRadius(0),
      css.borderStartEndRadius(0),
      css.borderEndEndRadius(0),
      css.firstChild(
        css.borderStartStartRadius(t.radius.md),
        css.borderStartEndRadius(t.radius.md),
      ),
      css.lastChild(css.borderEndStartRadius(t.radius.md), css.borderEndEndRadius(t.radius.md)),
    ),
  ),
  variants: {
    tone: {
      neutral: css.cn(
        css.bg(t.color.buttonBackground),
        css.color(t.color.text),
        css.border("1px solid", t.color.border),
        css.hover(
          css.bg(t.color.buttonBackgroundPressed),
          css.border("1px solid", t.color.borderHover),
        ),
      ),
      accent: css.cn(
        css.bg(t.color.highlight),
        css.color(t.color.onHighlight),
        css.border("1px solid", t.color.highlight),
        css.hover(
          css.bg(t.color.highlightPressed),
          css.border("1px solid", t.color.highlightPressed),
        ),
      ),
      quiet: css.cn(
        css.bg("transparent"),
        css.color(t.color.text),
        css.border("1px solid", "transparent"),
        css.hover(css.bg(t.color.buttonBackground)),
      ),
    },
    size: {
      sm: css.cn(css.padding(t.space._1, t.space._2), css.fontSize(t.font.sizeSm)),
      md: css.cn(css.padding(t.space._2, t.space._4), css.fontSize(t.font.size)),
    },
  },
  defaultVariants: { tone: "neutral", size: "md" },
});

/**
 * APG button, styled: a command button, and a toggle button with `isToggle`. `tone` and `size` are the look; `render`
 * replaces the `<button>` with another component or tag (`<a>` for a link that acts as a button). A pressed toggle, a
 * disabled button and the compact size are read off `aria-pressed`, `aria-disabled` and an ancestor's `data-size`; in a
 * `ButtonGroup` the corners two neighbours share are the group's, not the button's.
 */
export const Button = (props: ButtonProps): JSX.Element => {
  const buttonControl = createButton({
    get isToggle() {
      return props.isToggle;
    },
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    get disabled() {
      return props.disabled;
    },
    get onClick() {
      return props.onClick;
    },
    get onValueChange() {
      return props.onValueChange;
    },
  });
  // a structural prop, read once: it is the primitive for a fixture, not a signal
  untrack(() => props.onReady)?.(buttonControl);

  const rest = omit(
    props,
    "render",
    "tone",
    "size",
    "class",
    "children",
    "onReady",
    "isToggle",
    "value",
    "defaultValue",
    "disabled",
    "onClick",
    "onValueChange",
  );
  const merged = merge(buttonControl.buttonProps, rest, () => ({
    "data-part": "button",
    class: css.cn(button({ tone: props.tone, size: props.size }), props.class),
  }));
  const state: ButtonState = {
    pressed: buttonControl.pressed,
    disabled: () => props.disabled === true,
  };
  return renderPart(props, merged, state, (part) => <button {...part}>{props.children}</button>);
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

// The geometry of an edge: the straight line the diagram draws, and the curve the board draws (perfect-arrows).
import { getBoxToBoxArrow } from "perfect-arrows";

// The straight line between two boxes, trimmed to their borders, with its arrow head and the place of its label. The diagram
// and the board both draw edges with it, so a line that ends on a card is the same maths in both, and the geometry is in one
// file instead of two.

export interface RoutedPoint {
  readonly x: number;
  readonly y: number;
}

/** A box on the page: its corner, and its size when it has one (the default is a word or two). */
export interface RoutedBox {
  readonly x: number;
  readonly y: number;
  readonly width?: number | undefined;
  readonly height?: number | undefined;
}

export interface Route {
  /** Where the line starts and ends: both trimmed to the boxes' borders. */
  readonly from: RoutedPoint;
  readonly to: RoutedPoint;
  /** The arrow's three points, as `<polygon points>`. */
  readonly arrow: string;
  /** Where the label goes, and which way its text runs from there. */
  readonly label: RoutedPoint & { readonly along: boolean };
}

/** The box a node gets when the caller gives no size: enough for a word or two. */
const DEFAULT_BOX = { width: 120, height: 44 } as const;

/** A gap between a box's border and the line or the arrow's tip, so the arrow reads as pointing at it. */
const EDGE_GAP = 4;

/** The arrow head's length along the line, and half its width. */
const ARROW = 8;
const ARROW_HALF = 3.2;

/** How far an edge's label sits above (or beside) the line. */
const LABEL_OFFSET = 8;

const round = (value: number): number => Math.round(value * 100) / 100;

const point = (x: number, y: number): RoutedPoint => ({ x: round(x), y: round(y) });

const size = (box: RoutedBox): { readonly width: number; readonly height: number } => ({
  width: box.width ?? DEFAULT_BOX.width,
  height: box.height ?? DEFAULT_BOX.height,
});

const centreOf = (box: RoutedBox): RoutedPoint => {
  const { width, height } = size(box);
  return { x: box.x + width / 2, y: box.y + height / 2 };
};

/**
 * How far from a box's centre its border lies along a unit direction: the first of the two axis crossings, which is what an
 * axis-aligned rectangle meets.
 */
const borderOf = (box: RoutedBox, ux: number, uy: number): number => {
  const { width, height } = size(box);
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  const alongX = ux === 0 ? Number.POSITIVE_INFINITY : halfWidth / Math.abs(ux);
  const alongY = uy === 0 ? Number.POSITIVE_INFINITY : halfHeight / Math.abs(uy);
  return Math.min(alongX, alongY);
};

/** The line from one box's border to the other's, the arrow at the target's end, and the label at the middle. */
export const routeBetween = (from: RoutedBox, to: RoutedBox): Route | undefined => {
  const start = centreOf(from);
  const end = centreOf(to);
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const length = Math.hypot(dx, dy);
  if (length === 0) {
    return undefined;
  }
  const ux = dx / length;
  const uy = dy / length;
  const lineFrom = borderOf(from, ux, uy) + EDGE_GAP;
  const tip = length - borderOf(to, ux, uy) - EDGE_GAP;
  const lineTo = tip - ARROW;
  if (lineTo <= lineFrom) {
    return undefined;
  }
  const at = (distance: number): RoutedPoint =>
    point(start.x + ux * distance, start.y + uy * distance);
  const head = at(tip);
  const side = { x: -uy * ARROW_HALF, y: ux * ARROW_HALF };
  const arrow = [
    head,
    point(head.x - ux * ARROW + side.x, head.y - uy * ARROW + side.y),
    point(head.x - ux * ARROW - side.x, head.y - uy * ARROW - side.y),
  ]
    .map((corner) => `${corner.x},${corner.y}`)
    .join(" ");
  const middle = at((lineFrom + lineTo) / 2);
  // a line that runs across the page gets its label above it, one that runs down gets it beside: either way the text does not
  // sit on the line
  const along = Math.abs(ux) < Math.abs(uy);
  return {
    from: at(lineFrom),
    to: at(lineTo),
    arrow,
    label: along
      ? { x: round(middle.x + LABEL_OFFSET), y: round(middle.y + 4), along }
      : { x: middle.x, y: round(middle.y - LABEL_OFFSET), along },
  };
};

/** A curved edge: the path a `<path d>` takes, and the arrow head's three points for a `<polygon points>`. */
export interface Curve {
  readonly path: string;
  readonly head: string;
}

/** The head's length along the curve and half its width, in plane px. */
const HEAD_LENGTH = 9;
const HEAD_HALF = 4.2;

/**
 * perfect-arrows' box-to-box options: a light bow, a short gap at both ends, and straight lines where the boxes line up —
 * a map of two columns reads as columns, not as a nest of arcs. `padEnd` clears the target's border so the head points at
 * the card instead of touching it.
 */
const ARROW_CURVE = {
  bow: 0,
  stretch: 0.25,
  stretchMin: 40,
  stretchMax: 420,
  padStart: 6,
  padEnd: 14,
  straights: true,
} as const;

/** An arrow between two boxes that curves out of the way, from perfect-arrows (Steve Ruiz, MIT). */
export const curveBetween = (from: RoutedBox, to: RoutedBox): Curve | undefined => {
  const a = size(from);
  const b = size(to);
  const points = getBoxToBoxArrow(
    from.x,
    from.y,
    a.width,
    a.height,
    to.x,
    to.y,
    b.width,
    b.height,
    ARROW_CURVE,
  );
  const [sx, sy, cx, cy, ex, ey, angle] = points;
  if (sx === undefined || sy === undefined || cx === undefined || cy === undefined) {
    return undefined;
  }
  if (ex === undefined || ey === undefined || angle === undefined) {
    return undefined;
  }
  // the head sits on the curve's end, pointing the way the curve arrives
  const back = { x: ex - Math.cos(angle) * HEAD_LENGTH, y: ey - Math.sin(angle) * HEAD_LENGTH };
  const side = { x: -Math.sin(angle) * HEAD_HALF, y: Math.cos(angle) * HEAD_HALF };
  const head = [
    point(ex, ey),
    point(back.x + side.x, back.y + side.y),
    point(back.x - side.x, back.y - side.y),
  ]
    .map((corner) => `${corner.x},${corner.y}`)
    .join(" ");
  return {
    path: `M ${round(sx)} ${round(sy)} Q ${round(cx)} ${round(cy)} ${round(ex)} ${round(ey)}`,
    head,
  };
};

/**
 * A connector the CSS draws itself: the box the two cards live in, and one `shape()` in percentages of it. The same
 * string is a `border-shape` in a browser that has it and, through `shapePath`, the `d` of an SVG path everywhere else —
 * one description, two surfaces. The curve is a single cubic with both control points on the middle of the gap, so it
 * leaves and arrives square to a side and bows where the two cards do not line up.
 */
export interface Connector {
  readonly left: number;
  readonly top: number;
  readonly width: number;
  readonly height: number;
  /** `shape(from …)`; percentages, so it needs no size of its own. */
  readonly shape: string;
}

const percent = (value: number, of: number): string =>
  `${Math.round((of === 0 ? 0 : (value / of) * 100) * 1000) / 1000}%`;

/** The connector between two boxes, as the union box its percentages are against. */
export const connectorBetween = (from: RoutedBox, to: RoutedBox): Connector | undefined => {
  const a = size(from);
  const b = size(to);
  const left = Math.min(from.x, to.x);
  const top = Math.min(from.y, to.y);
  const width = Math.max(from.x + a.width, to.x + b.width) - left;
  const height = Math.max(from.y + a.height, to.y + b.height) - top;
  if (width <= 0 || height <= 0) {
    return undefined;
  }
  const fromCentre = centreOf(from);
  const toCentre = centreOf(to);
  const horizontal = Math.abs(toCentre.x - fromCentre.x) >= Math.abs(toCentre.y - fromCentre.y);
  // the border midpoint that faces the other card, on each side
  const start = horizontal
    ? {
        x: toCentre.x > fromCentre.x ? from.x + a.width : from.x,
        y: Math.min(Math.max(fromCentre.y, from.y), from.y + a.height),
      }
    : {
        x: Math.min(Math.max(fromCentre.x, from.x), from.x + a.width),
        y: toCentre.y > fromCentre.y ? from.y + a.height : from.y,
      };
  const end = horizontal
    ? {
        x: toCentre.x > fromCentre.x ? to.x : to.x + b.width,
        y: Math.min(Math.max(toCentre.y, to.y), to.y + b.height),
      }
    : {
        x: Math.min(Math.max(toCentre.x, to.x), to.x + b.width),
        y: toCentre.y > fromCentre.y ? to.y : to.y + b.height,
      };
  const middle = horizontal ? (start.x + end.x) / 2 : (start.y + end.y) / 2;
  const at = (p: RoutedPoint): string =>
    `${percent(p.x - left, width)} ${percent(p.y - top, height)}`;
  const c1 = horizontal ? { x: middle, y: start.y } : { x: start.x, y: middle };
  const c2 = horizontal ? { x: middle, y: end.y } : { x: end.x, y: middle };
  return {
    left,
    top,
    width,
    height,
    shape: `shape(from ${at(start)}, curve to ${at(end)} with ${at(c1)} / ${at(c2)})`,
  };
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The board's conformance: the plane is a named figure, the cards are the data (a token states the parts that use it, a part
// the tokens it uses), the current card dims what it does not reach, and the keyboard does what the pointer does — move a
// card with the arrows, pan and zoom the plane, drop the selection with Escape. The lines are decoration: every test here
// reads the DOM, and none of them needs a pointer to learn a relationship.
import type { JSX } from "@solidjs/web";
import { shapePath } from "@cssints/css-grammar/shape";
import { render } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";

import { connectorBetween } from "./route.ts";
import { Board, type BoardEdge, type BoardNode } from "./board.tsx";

const mount = (element: () => JSX.Element) => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(element, root);
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const NODES: ReadonlyArray<BoardNode> = [
  {
    id: "accent",
    kind: "token",
    x: 20,
    y: 20,
    width: 160,
    height: 90,
    title: "color.highlight",
    detail: "accent",
    swatch: "var(--color-highlight)",
  },
  {
    id: "radius",
    kind: "token",
    x: 20,
    y: 130,
    width: 160,
    height: 90,
    title: "radius.sm",
    detail: "6px",
  },
  { id: "button", kind: "part", x: 240, y: 20, width: 220, height: 150, title: "Button" },
  { id: "badge", kind: "part", x: 240, y: 190, width: 220, height: 120, title: "Badge" },
];

const EDGES: ReadonlyArray<BoardEdge> = [
  { from: "button", to: "accent" },
  { from: "button", to: "radius" },
  { from: "badge", to: "accent" },
];

const cards = (root: HTMLElement): HTMLElement[] => [
  ...root.querySelectorAll<HTMLElement>('[data-part="board-card"]'),
];

const card = (root: HTMLElement, id: string): HTMLElement =>
  root.querySelector<HTMLElement>(`[data-node="${id}"]`)!;

const head = (root: HTMLElement, id: string): HTMLButtonElement =>
  card(root, id).querySelector<HTMLButtonElement>('[data-part="board-head"]')!;

const viewport = (root: HTMLElement): HTMLElement =>
  root.querySelector<HTMLElement>('[data-part="board-viewport"]')!;

const plane = (root: HTMLElement): HTMLElement =>
  root.querySelector<HTMLElement>('[data-part="board-plane"]')!;

const key = (element: HTMLElement, init: KeyboardEventInit): void => {
  element.dispatchEvent(new KeyboardEvent("keydown", { bubbles: true, ...init }));
};

const pointer = (type: string, init: PointerEventInit): PointerEvent =>
  new PointerEvent(type, { bubbles: true, button: 0, ...init });

/** Solid 2 applies setters on the next flush, and the card's left/top follow it: two frames settle both. */
const settle = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

const board = () => <Board label="Design system" nodes={NODES} edges={EDGES} />;

/** The same board with each token saying which CSS property it feeds, which is what makes its value a field. */
const EDITABLE: ReadonlyArray<BoardNode> = [
  {
    id: "accent",
    kind: "token",
    x: 20,
    y: 20,
    width: 160,
    height: 90,
    title: "color.highlight",
    detail: "accent",
    property: "color",
    swatch: "var(--color-highlight)",
  },
  {
    id: "radius",
    kind: "token",
    x: 20,
    y: 130,
    width: 160,
    height: 90,
    title: "radius.sm",
    detail: "6px",
    property: "border-radius",
  },
  { id: "button", kind: "part", x: 240, y: 20, width: 220, height: 150, title: "Button" },
];

const EDITABLE_EDGES: ReadonlyArray<BoardEdge> = [{ from: "button", to: "accent" }];

const editable = () => (
  <Board label="Editable" nodes={EDITABLE} edges={EDITABLE_EDGES} />
);

/** Zoomed in, so the outline has somewhere to take the frame: at Fit the whole map is already in view. */
const outlined = () => <Board label="Outline" nodes={NODES} edges={EDGES} defaultScale={2} />;

const field = (root: HTMLElement, id: string): HTMLInputElement =>
  card(root, id).querySelector<HTMLInputElement>('[data-part="board-value"]')!;

/** A button of the board by its text: the settings bar's own controls. */
const control = (root: HTMLElement, label: string): HTMLButtonElement => {
  const found = [...root.querySelectorAll<HTMLButtonElement>("button")].find(
    (element) => element.textContent?.trim() === label,
  );
  if (found === undefined) {
    throw new Error(`board: no button "${label}"`);
  }
  return found;
};

describe("Board", () => {
  it("is a named figure whose cards are the data, in reading order", () => {
    const { root, dispose } = mount(board);
    expect(root.querySelector("figcaption")?.textContent).toContain("Design system");
    expect(cards(root).map((item) => item.getAttribute("data-node"))).toEqual([
      "accent",
      "radius",
      "button",
      "badge",
    ]);
    // the plane is the primitive's group, named by the board and described as a board rather than an image
    expect(viewport(root).getAttribute("role")).toBe("group");
    expect(viewport(root).getAttribute("aria-label")).toBe("Design system");
    expect(viewport(root).getAttribute("aria-roledescription")).toBe("board");
    dispose();
  });

  it("states every relationship as text, so the lines only repeat what the cards say", () => {
    const { root, dispose } = mount(board);
    expect(card(root, "button").textContent).toContain("Uses color.highlight, radius.sm");
    expect(card(root, "badge").textContent).toContain("Uses color.highlight");
    expect(card(root, "accent").textContent).toContain("Used by Button, Badge");
    expect(card(root, "radius").textContent).toContain("Used by Button");
    // the drawing is decoration over that text
    expect(root.querySelector('[data-part="board-edges"]')?.getAttribute("aria-hidden")).toBe(
      "true",
    );
    expect(root.querySelectorAll('[data-part="board-edge"]')).toHaveLength(EDGES.length);
    dispose();
  });

  it("makes a card current, dims what it does not reach, and drops it with Escape", async () => {
    const { root, dispose } = mount(board);
    head(root, "accent").click();
    await settle();
    expect(head(root, "accent").getAttribute("aria-current")).toBe("true");
    // the parts that use the token stay in, the token that does not is dimmed
    expect(card(root, "button").getAttribute("data-dim")).toBeNull();
    expect(card(root, "badge").getAttribute("data-dim")).toBeNull();
    expect(card(root, "radius").getAttribute("data-dim")).toBe("true");
    expect(root.querySelector('[data-part="board-status"]')?.textContent).toContain(
      "Used by Button, Badge",
    );

    key(viewport(root), { key: "Escape" });
    await settle();
    expect(head(root, "accent").getAttribute("aria-current")).toBeNull();
    expect(card(root, "radius").getAttribute("data-dim")).toBeNull();
    expect(root.querySelector('[data-part="board-status"]')?.textContent).toBe("");
    dispose();
  });

  it("moves a card with the pointer and keeps it whole on the plane", async () => {
    const { root, dispose } = mount(board);
    const item = card(root, "button");
    item.dispatchEvent(pointer("pointerdown", { pointerId: 1, clientX: 300, clientY: 100 }));
    item.dispatchEvent(pointer("pointermove", { pointerId: 1, clientX: 340, clientY: 130 }));
    await settle();
    expect(item.style.left).toBe("280px");
    expect(item.style.top).toBe("50px");

    // dragged far past the corner, the card stops at the edge instead of leaving the plane
    item.dispatchEvent(pointer("pointermove", { pointerId: 1, clientX: 5000, clientY: 5000 }));
    await settle();
    expect(Number.parseFloat(item.style.left)).toBeLessThanOrEqual(plane(root).clientWidth - 220);
    expect(Number.parseFloat(item.style.top)).toBeLessThanOrEqual(plane(root).clientHeight - 150);
    item.dispatchEvent(pointer("pointerup", { pointerId: 1 }));
    dispose();
  });

  it("nudges the focused card with the arrows, and pans the plane with the same keys", async () => {
    const { root, dispose } = mount(board);
    const item = card(root, "button");
    const button = head(root, "button");

    key(button, { key: "ArrowRight" });
    await settle();
    expect(item.style.left).toBe("248px");
    key(button, { key: "ArrowRight", shiftKey: true });
    await settle();
    expect(item.style.left).toBe("272px");
    // the card took the keys: the plane did not move with them
    expect(plane(root).style.transform).toContain("translate(0px, 0px)");

    key(viewport(root), { key: "ArrowRight" });
    await settle();
    expect(plane(root).style.transform).toContain("translate(24px, 0px)");
    dispose();
  });

  it("puts the plane under the theme's dark look, and takes it back", async () => {
    const { root, dispose } = mount(board);
    expect(viewport(root).getAttribute("data-mode")).toBe("light");
    const toggle = control(root, "Dark mode");
    expect(toggle.getAttribute("aria-pressed")).toBe("false");

    toggle.click();
    await settle();
    // the mode is the theme's `data-mode` scope over the plane, not a second palette
    expect(viewport(root).getAttribute("data-mode")).toBe("dark");
    expect(toggle.getAttribute("aria-pressed")).toBe("true");

    toggle.click();
    await settle();
    expect(viewport(root).getAttribute("data-mode")).toBe("light");
    dispose();
  });

  it("fits the whole map with the Fit button", async () => {
    const { root, dispose } = mount(board);
    const zoom = root.querySelector('[data-part="board-zoom"]')!;
    control(root, "Fit").click();
    await settle();
    // a map bigger than the frame: Fit is the smallest scale the plane allows
    expect(zoom.textContent).toBe("50%");
    expect(plane(root).style.transform).toContain("scale(0.5)");
    dispose();
  });

  it("zooms with the keys and says the scale", async () => {
    const { root, dispose } = mount(board);
    const zoom = root.querySelector('[data-part="board-zoom"]')!;
    expect(zoom.textContent).toBe("100%");

    key(viewport(root), { key: "+" });
    await settle();
    expect(zoom.textContent).toBe("125%");
    expect(plane(root).style.transform).toContain("scale(1.25)");

    // `0` is the overview: the smallest scale the plane allows, which is Fit
    key(viewport(root), { key: "0" });
    await settle();
    expect(zoom.textContent).toBe("50%");
    dispose();
  });

  it("edits a token's value on the plane, and refuses a value its property cannot take", async () => {
    const { root, dispose } = mount(editable);
    await settle();
    const world = root.querySelector<HTMLElement>('[data-part="board-world"]')!;
    const radius = field(root, "radius");
    // the field starts from the value the plane is using, not from the card's role text
    expect(radius.value).toBe("6px");
    // only a card that says which CSS property it feeds is a field: a part keeps its text, and no field
    expect(card(root, "button").querySelector('[data-part="board-value"]')).toBeNull();

    // a value the property refuses never reaches the plane, and the field says why
    radius.value = "not a length";
    key(radius, { key: "Enter" });
    await settle();
    expect(radius.getAttribute("aria-invalid")).toBe("true");
    expect(world.style.getPropertyValue("--radius-sm")).toBe("");

    radius.value = "12px";
    key(radius, { key: "Enter" });
    await settle();
    expect(radius.getAttribute("aria-invalid")).toBeNull();
    expect(world.style.getPropertyValue("--radius-sm")).toBe("12px");
    // the plane's own custom property, so anything under it follows: a part card, and a colour's swatch
    expect(getComputedStyle(card(root, "button")).getPropertyValue("--radius-sm").trim()).toBe("12px");

    // Escape abandons the draft, and an empty field is the theme's own value again
    radius.value = "3px";
    key(radius, { key: "Escape" });
    await settle();
    expect(radius.value).toBe("12px");
    expect(world.style.getPropertyValue("--radius-sm")).toBe("12px");

    radius.value = "";
    key(radius, { key: "Enter" });
    await settle();
    expect(world.style.getPropertyValue("--radius-sm")).toBe("");
    expect(radius.value).toBe("6px");

    // a colour token is the same edit: the card's swatch reads the token, so it follows the typed value
    const accent = field(root, "accent");
    expect(accent.value).not.toBe("accent");
    accent.value = "#123456";
    key(accent, { key: "Enter" });
    await settle();
    const swatch = card(root, "accent").querySelector<HTMLElement>('[data-part="board-swatch"]')!;
    expect(getComputedStyle(swatch).backgroundColor).toBe("rgb(18, 52, 86)");
    dispose();
  });

  it("lists the cards as an outline, and brings the one picked to the middle of the frame", async () => {
    const { root, dispose } = mount(outlined);
    await settle();
    const items = [...root.querySelectorAll<HTMLButtonElement>('[data-part="board-outline-item"]')];
    expect(items.map((item) => item.getAttribute("data-outline"))).toEqual([
      "accent",
      "radius",
      "button",
      "badge",
    ]);
    expect(items[3]?.textContent).toContain("Badge");
    expect(items[3]?.textContent).toContain("part · Uses color.highlight");

    items[3]!.click();
    await settle();
    const chosen = card(root, "badge").getBoundingClientRect();
    const frame = viewport(root).getBoundingClientRect();
    expect(
      Math.abs(chosen.left + chosen.width / 2 - (frame.left + frame.width / 2)),
    ).toBeLessThanOrEqual(1);
    expect(Math.abs(chosen.top + chosen.height / 2 - (frame.top + frame.height / 2))).toBeLessThanOrEqual(
      1,
    );
    // it is the current card, and the focus went with it, so the arrows move it next
    expect(head(root, "badge").getAttribute("aria-current")).toBe("true");
    expect(document.activeElement).toBe(head(root, "badge"));
    dispose();
  });
});

// A `line: "shape"` edge is one description in two surfaces: a border-shape (the CSS connector) and, where the property
// is missing, the same shape() as an SVG path. The test reads the shape and the path, so it holds in a browser without
// the property too, and it never assumes the Chrome that runs it has it.
it("draws a shape line as a border-shape, and the same curve as a path without it", () => {
  const nodes = [
    { id: "colour", kind: "token", x: 20, y: 20, width: 160, height: 90, title: "color.highlight" },
    { id: "button", kind: "part", x: 240, y: 20, width: 220, height: 150, title: "Button" },
  ] satisfies ReadonlyArray<BoardNode>;
  const edges = [
    { from: "colour", to: "button", line: "shape" },
  ] satisfies ReadonlyArray<BoardEdge>;
  const mounted = mount(() => <Board label="Connector" nodes={nodes} edges={edges} />);
  const element = mounted.root.querySelector<HTMLElement>('[data-part="board-connector"]');
  expect(element).not.toBeNull();
  const shape = element!.style.getPropertyValue("--_shape");
  const expected = connectorBetween(nodes[0]!, nodes[1]!);
  expect(shape).toBe(expected!.shape);
  expect(shape.startsWith("shape(from ")).toBe(true);
  // the box is the union of the two cards, which is what the percentages are against
  expect(element!.style.left).toBe(`${expected!.left}px`);
  expect(element!.style.width).toBe(`${expected!.width}px`);
  // the fallback is the same value: one description, two surfaces
  const fallback = element!.querySelector<HTMLElement>('[data-part="board-connector-fallback"]')!;
  expect(fallback.querySelector("path")!.getAttribute("d")).toBe(shapePath(shape).d);
  const native = element!.querySelector<HTMLElement>('[data-part="board-connector-native"]')!;
  const supports = CSS.supports("border-shape", "shape(from 0 0, line to 1px 1px)");
  // one of the two paints: the border where the property is there, the path where it is not
  expect(getComputedStyle(fallback).display === "none").toBe(supports);
  expect(getComputedStyle(native).borderTopWidth).toBe(supports ? "2px" : "0px");
  mounted.dispose();
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
